/**
 * Normalizes any language string to one of the 9 canonical keys in the dictionary.
 */
export function normalizeLanguageKey(language = 'English') {
  if (!language) return 'English';
  const l = String(language).toLowerCase().trim();

  if (l.includes('hindi') || l.includes('हिन्दी')) return 'Hindi (हिन्दी)';
  if (l.includes('kannada') || l.includes('ಕನ್ನಡ')) return 'Kannada (ಕನ್ನಡ)';
  if (l.includes('tamil') || l.includes('தமிழ்')) return 'Tamil (தமிழ்)';
  if (l.includes('korean') || l.includes('한국어') || l.startsWith('ko')) return 'Korean (한국어)';
  if (l.includes('spanish') || l.includes('español') || l.startsWith('es')) return 'Spanish (Español)';
  if (l.includes('french') || l.includes('français') || l.startsWith('fr')) return 'French (Français)';
  if (l.includes('german') || l.includes('deutsch') || l.startsWith('de')) return 'German (Deutsch)';
  if (l.includes('japanese') || l.includes('日本語') || l.startsWith('ja')) return 'Japanese (日本語)';

  return 'English';
}

/**
 * Returns the proper BCP-47 locale code for Intl.DateTimeFormat
 */
export function getLanguageLocale(language = 'English') {
  const norm = normalizeLanguageKey(language);
  switch (norm) {
    case 'Hindi (हिन्दी)': return 'hi-IN';
    case 'Kannada (ಕನ್ನಡ)': return 'kn-IN';
    case 'Tamil (தமிழ்)': return 'ta-IN';
    case 'Korean (한국어)': return 'ko-KR';
    case 'Spanish (Español)': return 'es-ES';
    case 'French (Français)': return 'fr-FR';
    case 'German (Deutsch)': return 'de-DE';
    case 'Japanese (日本語)': return 'ja-JP';
    default: return 'en-US';
  }
}

/**
 * Formats a Date using the appropriate locale for the current language.
 */
export function formatLocalizedDate(date, language = 'English', options = {}) {
  const locale = getLanguageLocale(language);
  const d = date instanceof Date ? date : new Date(date);
  if (isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat(locale, options).format(d);
}

/**
 * Safely fetches translated text for the current language with parameter replacement.
 * e.g. getTranslation(lang, 'dash.willItRain', 'Will it rain in {city}?', { city: 'Paris' })
 */
export function getTranslation(language = 'English', key = '', fallbackText = '', params = {}) {
  if (!key) return fallbackText;

  const canonLang = normalizeLanguageKey(language);
  let template = fallbackText || key;

  // 1. Check normalized language dictionary
  if (translations[canonLang] && translations[canonLang][key] !== undefined) {
    template = translations[canonLang][key];
  } else if (translations['English'] && translations['English'][key] !== undefined) {
    // 2. Fallback to English dictionary
    template = translations['English'][key];
  }

  // 3. Replace {param} placeholders if provided
  if (params && typeof params === 'object') {
    Object.entries(params).forEach(([paramKey, paramVal]) => {
      template = template.replaceAll(`{${paramKey}}`, String(paramVal));
    });
  }

  return template;
}

