/**
 * Translates a dynamic weather condition string (e.g. from WeatherAPI) to the user's selected language.
 */
export function translateCondition(condition = '', language = 'English') {
  if (!condition) return '';
  const normLang = normalizeLanguageKey(language);
  if (normLang === 'English') return condition;

  const lower = condition.toLowerCase();

  for (const [englishKey, transMap] of Object.entries(WEATHER_CONDITIONS)) {
    if (lower.includes(englishKey.toLowerCase())) {
      return transMap[normLang] || condition;
    }
  }

  // Common keyword fallbacks
  if (lower.includes('rain') || lower.includes('drizzle') || lower.includes('shower')) {
    return WEATHER_CONDITIONS['Rain'][normLang] || condition;
  }
  if (lower.includes('sun') || lower.includes('clear')) {
    return WEATHER_CONDITIONS['Sunny'][normLang] || condition;
  }
  if (lower.includes('cloud')) {
    return WEATHER_CONDITIONS['Partly Cloudy'][normLang] || condition;
  }
  if (lower.includes('thunder') || lower.includes('storm')) {
    return WEATHER_CONDITIONS['Thunderstorm'][normLang] || condition;
  }
  if (lower.includes('snow') || lower.includes('ice') || lower.includes('blizzard')) {
    return WEATHER_CONDITIONS['Snow'][normLang] || condition;
  }
  if (lower.includes('fog') || lower.includes('mist')) {
    return WEATHER_CONDITIONS['Fog'][normLang] || condition;
  }

  return condition;
}
